DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_TEXT_1','The Threshold Court[NEWLINE]A paid defensive reinforcement network between owned cities[NEWLINE]Science or supported Domination[NEWLINE][NEWLINE]Build Houses in useful cities and use the network to move an existing melee defender where distance would otherwise be decisive. One crossing per turn and arrival exhaustion make this a reinforcement tool, not an instant attacking swarm.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_TEXT_2','Develop at least two viable cities with an ordinary economy and defense. The network does not begin with free Houses. Plan endpoints around cities worth protecting and reserve the Gold needed for an emergency crossing.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_TEXT_3','Keep a mobile eligible unit at a ready origin and an empty military slot at the intended destination. Rotate departures among cities as origin cooldowns permit. Hingeguards support territorial defense while normal units cover ranged, siege and naval roles.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_TEXT_4','Use the network to maintain distant fronts without abandoning local support. Send a unit before its offensive action is needed, because arrival consumes movement and attacks until the next originating owner-turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_TEXT_5','- A valid crossing has no distance or ordinary pathfinding limit.[NEWLINE]- The same existing unit retains its identity and experience.[NEWLINE]- Several origins can support a rotating long-distance defense.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_TEXT_6','- The empire gets only one successful crossing per owner-turn.[NEWLINE]- Origins recharge, Gold is required, and an occupied destination is unavailable.[NEWLINE]- Only eligible land melee military units qualify; arrival is exhausted.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_TEXT_7','- Pressure several cities at once or use a sustained siege that one arrival cannot solve.[NEWLINE]- Threaten the treasury and approach before Houses are established.[NEWLINE]- Use ranged, naval and logistical pressure instead of assuming every threatened city is isolated.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_TEXT_8','- Blocking the destination with a combat unit while expecting another to arrive.[NEWLINE]- Trying to send a civilian, ranged or siege unit.[NEWLINE]- Planning an immediate attack or upgrade by the exhausted arrival.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Beyond the Sky: A distant city can receive a defender without travelling the route a fast raider expected to exploit.[NEWLINE][NEWLINE]McPvP: A timely arrival can contest an objective city or return approach before a mobile raider completes the plan.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Several simultaneous fronts can exceed the single-crossing limit.[NEWLINE][NEWLINE]The Filthy Realm: A city-focused shutdown or economic disruption can tax the Gold and local support on which reinforcement depends.');
