INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_LEADER_BACKGROUND','Build Houses in useful cities and use the network to move an existing melee defender where distance would otherwise be decisive. One crossing per turn and arrival exhaustion make this a reinforcement tool, not an instant attacking swarm.');
