INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_STRATEGY','Build Houses in useful cities and use the network to move an existing melee defender where distance would otherwise be decisive. One crossing per turn and arrival exhaustion make this a reinforcement tool, not an instant attacking swarm.[NEWLINE][NEWLINE]Develop at least two viable cities with an ordinary economy and defense. The network does not begin with free Houses. Plan endpoints around cities worth protecting and reserve the Gold needed for an emergency crossing.[NEWLINE][NEWLINE]Keep a mobile eligible unit at a ready origin and an empty military slot at the intended destination. Rotate departures among cities as origin cooldowns permit. Hingeguards support territorial defense while normal units cover ranged, siege and naval roles.[NEWLINE][NEWLINE]Use the network to maintain distant fronts without abandoning local support. Send a unit before its offensive action is needed, because arrival consumes movement and attacks until the next originating owner-turn.');
