INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_LEADER_TEXT_2','Develop at least two viable cities with an ordinary economy and defense. The network does not begin with free Houses. Plan endpoints around cities worth protecting and reserve the Gold needed for an emergency crossing.[NEWLINE][NEWLINE]Keep a mobile eligible unit at a ready origin and an empty military slot at the intended destination. Rotate departures among cities as origin cooldowns permit. Hingeguards support territorial defense while normal units cover ranged, siege and naval roles.[NEWLINE][NEWLINE]Use the network to maintain distant fronts without abandoning local support. Send a unit before its offensive action is needed, because arrival consumes movement and attacks until the next originating owner-turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETHRESHOLDCOURT_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Beyond the Sky: A distant city can receive a defender without travelling the route a fast raider expected to exploit.[NEWLINE][NEWLINE]McPvP: A timely arrival can contest an objective city or return approach before a mobile raider completes the plan.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Several simultaneous fronts can exceed the single-crossing limit.[NEWLINE][NEWLINE]The Filthy Realm: A city-focused shutdown or economic disruption can tax the Gold and local support on which reinforcement depends.');
